import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, "..");
const nexusBinary = process.argv[2] ? path.resolve(process.argv[2]) : "nexus";

const docFiles = [
  "README.md",
  "quickstart.md",
  "docs/USER_MANUAL.md",
  "docs/CLIENT_GUIDE.md",
  "docs/CLOUD_PROVIDERS.md",
];

function splitWords(cmd) {
  const tokens = [];
  let current = "";
  let inDouble = false;
  let inSingle = false;
  for (let i = 0; i < cmd.length; i++) {
    const c = cmd[i];
    if (c === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (c === "'" && !inDouble) {
      inSingle = !inSingle;
    } else if (/\s/.test(c) && !inDouble && !inSingle) {
      if (current.length > 0) {
        tokens.push(current);
        current = "";
      }
    } else {
      current += c;
    }
  }
  if (current.length > 0) tokens.push(current);
  return tokens;
}

const commandsToTest = [];

for (const relPath of docFiles) {
  const absPath = path.resolve(repoRoot, relPath);
  if (!fs.existsSync(absPath)) {
    console.warn(`Warning: doc file not found: ${relPath}`);
    continue;
  }
